  interface SeedVariant {
    sku: string;
    nameFa?: string;
    nameEn?: string;
    stock: number;
    price?: number;
    attributes?: Record<string, string>;
  }
  interface SeedProduct {
    slug: string;
    nameFa: string;
    nameEn: string;
    descriptionFa: string;
    descriptionEn: string;
    category: string;
    brand?: string;
    basePrice: number;
    featured?: boolean;
    isNew?: boolean;
    attributes?: Record<string, string>;
    variants: SeedVariant[];
    rating: number;
    soldCount: number;
  }

