  const sizeVariants = (prefix: string, rows: Array<[string, number, number?]>): SeedVariant[] =>
    rows.map(([size, stock, extra]) => ({
      sku: `${prefix}-${size}`,
      nameFa: `سایز ${size}`,
      nameEn: `Size ${size}`,
      stock,
      price: extra,
      attributes: { size },
    }));

